{"command":"mkdir -p internal/funcs
cat << 'EOF' > internal/funcs/math.go
package funcs

import (
	"fmt"
	"math"
	"reflect"
	"strconv"

	gomplateMath "gomplate/math"
)

type MathFuncs struct{}

func (m *MathFuncs) IsInt(v interface{}) bool {
	if v == nil {
		return false
	}
	val := reflect.ValueOf(v)
	switch val.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return true
	default:
		return false
	}
}

func (m *MathFuncs) IsFloat(v interface{}) bool {
	if v == nil {
		return false
	}
	val := reflect.ValueOf(v)
	switch val.Kind() {
	case reflect.Float32, reflect.Float64:
		return true
	default:
		return false
	}
}

func (m *MathFuncs) IsNum(v interface{}) bool {
	return m.IsInt(v) || m.IsFloat(v)
}

func toFloat64(v interface{}) (float64, error) {
	if v == nil {
		return 0, fmt.Errorf("nil value")
	}
	val := reflect.ValueOf(v)
	switch val.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return float64(val.Int()), nil
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return float64(val.Uint()), nil
	case reflect.Float32, reflect.Float64:
		return val.Float(), nil
	case reflect.String:
		return strconv.ParseFloat(val.String(), 64)
	default:
		return 0, fmt.Errorf("cannot convert %v to float64", v)
	}
}

func toInt64(v interface{}) (int64, error) {
	if v == nil {
		return 0, fmt.Errorf("nil value")
	}
	val := reflect.ValueOf(v)
	switch val.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return val.Int(), nil
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return int64(val.Uint()), nil
	case reflect.Float32, reflect.Float64:
		return int64(val.Float()), nil
	case reflect.String:
		return strconv.ParseInt(val.String(), 10, 64)
	default:
		return 0, fmt.Errorf("cannot convert %v to int64", v)
	}
}

func (m *MathFuncs) Add(n ...interface{}) (interface{}, error) {
	if len(n) == 0 {
		return int64(0), nil
	}
	hasFloat := false
	for _, v := range n {
		if m.IsFloat(v) {
			hasFloat = true
			break
		}
	}
	if hasFloat {
		var sum float64
		for _, v := range n {
			f, err := toFloat64(v)
			if err != nil {
				return nil, err
			}
			sum += f
		}
		return sum, nil
	}
	var sum int64
	for _, v := range n {
		i, err := toInt64(v)
		if err != nil {
			return nil, err
		}
		sum += i
	}
	return sum, nil
}

func (m *MathFuncs) Sub(a, b interface{}) (interface{}, error) {
	if m.IsFloat(a) || m.IsFloat(b) {
		fa, err1 := toFloat64(a)
		fb, err2 := toFloat64(b)
		if err1 != nil || err2 != nil {
			return nil, fmt.Errorf("invalid operand for sub")
		}
		return fa - fb, nil
	}
	ia, err1 := toInt64(a)
	ib, err2 := toInt64(b)
	if err1 != nil || err2 != nil {
		return nil, fmt.Errorf("invalid operand for sub")
	}
	return ia - ib, nil
}

func (m *MathFuncs) Mul(n ...interface{}) (interface{}, error) {
	if len(n) == 0 {
		return int64(0), nil
	}
	hasFloat := false
	for _, v := range n {
		if m.IsFloat(v) {
			hasFloat = true
			break
		}
	}
	if hasFloat {
		var prod float64 = 1
		for _, v := range n {
			f, err := toFloat64(v)
			if err != nil {
				return nil, err
			}
			prod *= f
		}
		return prod, nil
	}
	var prod int64 = 1
	for _, v := range n {
		i, err := toInt64(v)
		if err != nil {
			return nil, err
		}
		prod *= i
	}
	return prod, nil
}

func (m *MathFuncs) Div(a, b interface{}) (interface{}, error) {
	fa, err1 := toFloat64(a)
	fb, err2 := toFloat64(b)
	if err1 != nil || err2 != nil {
		return nil, fmt.Errorf("invalid operand for div")
	}
	if fb == 0 {
		return nil, fmt.Errorf("division by zero")
	}
	res := fa / fb
	if !m.IsFloat(a) && !m.IsFloat(b) && math.Mod(fa, fb) == 0 {
		return int64(res), nil
	}
	return res, nil
}

func (m *MathFuncs) Rem(a, b interface{}) (interface{}, error) {
	ia, err1 := toInt64(a)
	ib, err2 := toInt64(b)
	if err1 != nil || err2 != nil {
		return nil, fmt.Errorf("invalid operand for rem")
	}
	if ib == 0 {
		return nil, fmt.Errorf("division by zero")
	}
	return ia % ib, nil
}

func (m *MathFuncs) Pow(a, b interface{}) (interface{}, error) {
	fa, err1 := toFloat64(a)
	fb, err2 := toFloat64(b)
	if err1 != nil || err2 != nil {
		return nil, fmt.Errorf("invalid operand for pow")
	}
	res := math.Pow(fa, fb)
	if !m.IsFloat(a) && !m.IsFloat(b) && fb >= 0 {
		return int64(res), nil
	}
	return res, nil
}

func (m *MathFuncs) Abs(n interface{}) (interface{}, error) {
	if m.IsFloat(n) {
		f, err := toFloat64(n)
		if err != nil {
			return nil, err
		}
		return math.Abs(f), nil
	}
	i, err := toInt64(n)
	if err != nil {
		return nil, err
	}
	if i < 0 {
		return -i, nil
	}
	return i, nil
}

func (m *MathFuncs) Ceil(n interface{}) (interface{}, error) {
	f, err := toFloat64(n)
	if err != nil {
		return nil, err
	}
	return int64(math.Ceil(f)), nil
}

func (m *MathFuncs) Floor(n interface{}) (interface{}, error) {
	f, err := toFloat64(n)
	if err != nil {
		return nil, err
	}
	return int64(math.Floor(f)), nil
}

func (m *MathFuncs) Round(n interface{}) (interface{}, error) {
	f, err := toFloat64(n)
	if err != nil {
		return nil, err
	}
	return int64(math.Round(f)), nil
}

func (m *MathFuncs) Min(a interface{}, n ...interface{}) (interface{}, error) {
	minVal, err := toFloat64(a)
	if err != nil {
		return nil, err
	}
	isFloat := m.IsFloat(a)
	for _, v := range n {
		if m.IsFloat(v) {
			isFloat = true
		}
		f, err := toFloat64(v)
		if err != nil {
			return nil, err
		}
		if f < minVal {
			minVal = f
		}
	}
	if isFloat {
		return minVal, nil
	}
	return int64(minVal), nil
}

func (m *MathFuncs) Max(a interface{}, n ...interface{}) (interface{}, error) {
	maxVal, err := toFloat64(a)
	if err != nil {
		return nil, err
	}
	isFloat := m.IsFloat(a)
	for _, v := range n {
		if m.IsFloat(v) {
			isFloat = true
		}
		f, err := toFloat64(v)
		if err != nil {
			return nil, err
		}
		if f > maxVal {
			maxVal = f
		}
	}
	if isFloat {
		return maxVal, nil
	}
	return int64(maxVal), nil
}

func (m *MathFuncs) Seq(args ...interface{}) ([]int64, error) {
	if len(args) == 0 {
		return []int64{}, nil
	}
	var start, end, step int64 = 1, 0, 1
	var err error
	if len(args) == 1 {
		end, err = toInt64(args[0])
		if err != nil {
			return nil, err
		}
	} else if len(args) == 2 {
		start, err = toInt64(args[0])
		if err != nil {
			return nil, err
		}
		end, err = toInt64(args[1])
		if err != nil {
			return nil, err
		}
	} else if len(args) >= 3 {
		start, err = toInt64(args[0])
		if err != nil {
			return nil, err
		}
		end, err = toInt64(args[1])
		if err != nil {
			return nil, err
		}
		step, err = toInt64(args[2])
		if err != nil {
			return nil, err
		}
	}
	return gomplateMath.Seq(start, end, step), nil
}
EOF
"}

