package funcs

import (
	"fmt"
	"regexp"
	"strings"
	"unicode"
	"unicode/utf8"
)

type StringFuncs struct{}

func (s *StringFuncs) Abbrev(args ...interface{}) (string, error) {
	if len(args) < 2 {
		return "", fmt.Errorf("abbrev requires width and string")
	}
	var width int
	var offset int
	var str string

	if len(args) == 2 {
		w, err := toInt64(args[0])
		if err != nil {
			return "", err
		}
		width = int(w)
		str = fmt.Sprint(args[1])
	} else {
		o, err1 := toInt64(args[0])
		w, err2 := toInt64(args[1])
		if err1 != nil || err2 != nil {
			return "", fmt.Errorf("invalid width/offset")
		}
		offset = int(o)
		width = int(w)
		str = fmt.Sprint(args[2])
	}

	if len(str) <= width {
		return str, nil
	}
	if width < 4 {
		return "", fmt.Errorf("minimum width for abbrev is 4")
	}
	if offset > 0 {
		if offset+width-3 < len(str) {
			return "..." + str[offset:offset+width-6] + "...", nil
		}
		return "..." + str[len(str)-(width-3):], nil
	}
	return str[:width-3] + "...", nil
}

func (s *StringFuncs) CamelCase(str string) string {
	parts := splitWords(str)
	var sb strings.Builder
	for i, p := range parts {
		if i == 0 {
			sb.WriteString(strings.ToLower(p))
		} else {
			sb.WriteString(titleCase(p))
		}
	}
	return sb.String()
}

func (s *StringFuncs) SnakeCase(str string) string {
	parts := splitWords(str)
	for i, p := range parts {
		parts[i] = strings.ToLower(p)
	}
	return strings.Join(parts, "_")
}

func (s *StringFuncs) KebabCase(str string) string {
	parts := splitWords(str)
	for i, p := range parts {
		parts[i] = strings.ToLower(p)
	}
	return strings.Join(parts, "-")
}

func splitWords(s string) []string {
	var words []string
	var current strings.Builder
	var lastRune rune

	for _, r := range s {
		if !unicode.IsLetter(r) && !unicode.IsNumber(r) {
			if current.Len() > 0 {
				words = append(words, current.String())
				current.Reset()
			}
		} else {
			if unicode.IsUpper(r) && current.Len() > 0 && unicode.IsLower(lastRune) {
				words = append(words, current.String())
				current.Reset()
			}
			current.WriteRune(r)
		}
		lastRune = r
	}
	if current.Len() > 0 {
		words = append(words, current.String())
	}
	return words
}

func titleCase(s string) string {
	if s == "" {
		return ""
	}
	r, size := utf8.DecodeRuneInString(s)
	return string(unicode.ToTitle(r)) + strings.ToLower(s[size:])
}

func (s *StringFuncs) Contains(substr, str string) bool {
	return strings.Contains(str, substr)
}

func (s *StringFuncs) HasPrefix(prefix, str string) bool {
	return strings.HasPrefix(str, prefix)
}

func (s *StringFuncs) HasSuffix(suffix, str string) bool {
	return strings.HasSuffix(str, suffix)
}

func (s *StringFuncs) Indent(args ...interface{}) (string, error) {
	indentation := "  "
	str := ""
	if len(args) == 1 {
		str = fmt.Sprint(args[0])
	} else if len(args) == 2 {
		switch v := args[0].(type) {
		case int, int64, float64:
			n, _ := toInt64(v)
			indentation = strings.Repeat(" ", int(n))
		default:
			indentation = fmt.Sprint(v)
		}
		str = fmt.Sprint(args[1])
	}

	lines := strings.Split(str, "\n")
	for i, line := range lines {
		if line != "" {
			lines[i] = indentation + line
		}
	}
	return strings.Join(lines, "\n"), nil
}

func (s *StringFuncs) SkipLines(count int, str string) string {
	lines := strings.Split(str, "\n")
	if count >= len(lines) {
		return ""
	}
	return strings.Join(lines[count:], "\n")
}

func (s *StringFuncs) Split(sep, str string) []string {
	return strings.Split(str, sep)
}

func (s *StringFuncs) SplitN(sep string, count int, str string) []string {
	return strings.SplitN(str, sep, count)
}

func (s *StringFuncs) Quote(str string) string {
	return fmt.Sprintf("%q", str)
}

func (s *StringFuncs) Squote(str string) string {
	return fmt.Sprintf("'%s'", strings.ReplaceAll(str, "'", "\\'"))
}

func (s *StringFuncs) ShellQuote(str string) string {
	return fmt.Sprintf("'%s'", strings.ReplaceAll(str, "'", "'\\''"))
}

func (s *StringFuncs) Repeat(count int, str string) string {
	if count < 0 {
		return ""
	}
	return strings.Repeat(str, count)
}

func (s *StringFuncs) ReplaceAll(old, newStr, str string) string {
	return strings.ReplaceAll(str, old, newStr)
}

func (s *StringFuncs) Slug(str string) string {
	str = strings.ToLower(str)
	reg := regexp.MustCompile(`[^a-z0-9]+`)
	str = reg.ReplaceAllString(str, "-")
	return strings.Trim(str, "-")
}

func (s *StringFuncs) Title(str string) string {
	words := strings.Fields(str)
	for i, w := range words {
		words[i] = titleCase(w)
	}
	return strings.Join(words, " ")
}

func (s *StringFuncs) ToLower(str string) string {
	return strings.ToLower(str)
}

func (s *StringFuncs) ToUpper(str string) string {
	return strings.ToUpper(str)
}

func (s *StringFuncs) Trim(cutset, str string) string {
	return strings.Trim(str, cutset)
}

func (s *StringFuncs) TrimLeft(cutset, str string) string {
	return strings.TrimLeft(str, cutset)
}

func (s *StringFuncs) TrimPrefix(prefix, str string) string {
	return strings.TrimPrefix(str, prefix)
}

func (s *StringFuncs) TrimRight(cutset, str string) string {
	return strings.TrimRight(str, cutset)
}

func (s *StringFuncs) TrimSpace(str string) string {
	return strings.TrimSpace(str)
}

func (s *StringFuncs) TrimSuffix(suffix, str string) string {
	return strings.TrimSuffix(str, suffix)
}

func (s *StringFuncs) Trunc(length int, str string) string {
	if length <= 0 {
		return ""
	}
	runes := []rune(str)
	if len(runes) <= length {
		return str
	}
	return string(runes[:length])
}

func (s *StringFuncs) RuneCount(str string) int {
	return utf8.RuneCountInString(str)
}

func (s *StringFuncs) WordWrap(args ...interface{}) (string, error) {
	if len(args) == 0 {
		return "", fmt.Errorf("wordWrap requires at least 1 argument")
	}
	width := 80
	str := ""
	if len(args) == 1 {
		str = fmt.Sprint(args[0])
	} else {
		w, _ := toInt64(args[0])
		width = int(w)
		str = fmt.Sprint(args[1])
	}
	if width <= 0 {
		return str, nil
	}
	words := strings.Fields(str)
	if len(words) == 0 {
		return "", nil
	}
	var sb strings.Builder
	lineLen := 0
	for _, w := range words {
		wLen := utf8.RuneCountInString(w)
		if lineLen == 0 {
			sb.WriteString(w)
			lineLen = wLen
		} else if lineLen+1+wLen <= width {
			sb.WriteString(" ")
			sb.WriteString(w)
			lineLen += 1 + wLen
		} else {
			sb.WriteString("\n")
			sb.WriteString(w)
			lineLen = wLen
		}
	}
	return sb.String(), nil
}
EOF
