{"command":"cat << 'EOF' > internal/funcs/coll.go
package funcs

import (
	"fmt"
	"reflect"
	"sort"
)

type CollFuncs struct{}

func (c *CollFuncs) Dict(kv ...interface{}) (map[string]interface{}, error) {
	if len(kv)%2 != 0 {
		return nil, fmt.Errorf("dict requires an even number of arguments")
	}
	m := make(map[string]interface{})
	for i := 0; i < len(kv); i += 2 {
		key := fmt.Sprint(kv[i])
		m[key] = kv[i+1]
	}
	return m, nil
}

func (c *CollFuncs) Slice(items ...interface{}) []interface{} {
	if len(items) == 0 {
		return []interface{}{}
	}
	return items
}

func (c *CollFuncs) GoSlice(items ...interface{}) []interface{} {
	return c.Slice(items...)
}

func (c *CollFuncs) Has(coll interface{}, keyVal interface{}) bool {
	if coll == nil {
		return false
	}
	v := reflect.ValueOf(coll)
	switch v.Kind() {
	case reflect.Map:
		k := reflect.ValueOf(keyVal)
		if k.IsValid() && k.Type().AssignableTo(v.Type().Key()) {
			return v.MapIndex(k).IsValid()
		}
		// Convert keyVal to map key string if needed
		sk := fmt.Sprint(keyVal)
		for _, mapKey := range v.MapKeys() {
			if fmt.Sprint(mapKey.Interface()) == sk {
				return true
			}
		}
	case reflect.Slice, reflect.Array:
		target := fmt.Sprint(keyVal)
		for i := 0; i < v.Len(); i++ {
			elem := fmt.Sprint(v.Index(i).Interface())
			if elem == target {
				return true
			}
		}
	}
	return false
}

func (c *CollFuncs) Index(coll interface{}, keys ...interface{}) (interface{}, error) {
	curr := coll
	for _, key := range keys {
		if curr == nil {
			return nil, nil
		}
		v := reflect.ValueOf(curr)
		if v.Kind() == reflect.Map {
			found := false
			sk := fmt.Sprint(key)
			for _, mapKey := range v.MapKeys() {
				if fmt.Sprint(mapKey.Interface()) == sk {
					curr = v.MapIndex(mapKey).Interface()
					found = true
					break
				}
			}
			if !found {
				return nil, nil
			}
		} else if v.Kind() == reflect.Slice || v.Kind() == reflect.Array {
			idx, err := toInt64(key)
			if err != nil || idx < 0 || int(idx) >= v.Len() {
				return nil, nil
			}
			curr = v.Index(int(idx)).Interface()
		} else {
			return nil, nil
		}
	}
	return curr, nil
}

func (c *CollFuncs) Keys(in interface{}) ([]string, error) {
	if in == nil {
		return []string{}, nil
	}
	v := reflect.ValueOf(in)
	if v.Kind() != reflect.Map {
		return nil, fmt.Errorf("keys expects a map")
	}
	keys := make([]string, 0, v.Len())
	for _, mapKey := range v.MapKeys() {
		keys = append(keys, fmt.Sprint(mapKey.Interface()))
	}
	sort.Strings(keys)
	return keys, nil
}

func (c *CollFuncs) Values(in interface{}) ([]interface{}, error) {
	if in == nil {
		return []interface{}{}, nil
	}
	v := reflect.ValueOf(in)
	if v.Kind() != reflect.Map {
		return nil, fmt.Errorf("values expects a map")
	}
	keys := make([]string, 0, v.Len())
	mapKeys := v.MapKeys()
	keyMap := make(map[string]reflect.Value)
	for _, mapKey := range mapKeys {
		sk := fmt.Sprint(mapKey.Interface())
		keys = append(keys, sk)
		keyMap[sk] = mapKey
	}
	sort.Strings(keys)
	values := make([]interface{}, 0, len(keys))
	for _, k := range keys {
		values = append(values, v.MapIndex(keyMap[k]).Interface())
	}
	return values, nil
}

func (c *CollFuncs) Append(item interface{}, list interface{}) ([]interface{}, error) {
	s, err := toInterfaceSlice(list)
	if err != nil {
		return nil, err
	}
	return append(s, item), nil
}

func (c *CollFuncs) Prepend(item interface{}, list interface{}) ([]interface{}, error) {
	s, err := toInterfaceSlice(list)
	if err != nil {
		return nil, err
	}
	return append([]interface{}{item}, s...), nil
}

func toInterfaceSlice(v interface{}) ([]interface{}, error) {
	if v == nil {
		return []interface{}{}, nil
	}
	val := reflect.ValueOf(v)
	if val.Kind() != reflect.Slice && val.Kind() != reflect.Array {
		return nil, fmt.Errorf("expected slice/array, got %T", v)
	}
	res := make([]interface{}, val.Len())
	for i := 0; i < val.Len(); i++ {
		res[i] = val.Index(i).Interface()
	}
	return res, nil
}

func (c *CollFuncs) Uniq(in interface{}) ([]interface{}, error) {
	s, err := toInterfaceSlice(in)
	if err != nil {
		return nil, err
	}
	seen := make(map[string]bool)
	res := make([]interface{}, 0, len(s))
	for _, item := range s {
		key := fmt.Sprintf("%v", item)
		if !seen[key] {
			seen[key] = true
			res = append(res, item)
		}
	}
	return res, nil
}

func (c *CollFuncs) Flatten(in interface{}) ([]interface{}, error) {
	s, err := toInterfaceSlice(in)
	if err != nil {
		return nil, err
	}
	var res []interface{}
	var flattenHelper func(item interface{})
	flattenHelper = func(item interface{}) {
		v := reflect.ValueOf(item)
		if item != nil && (v.Kind() == reflect.Slice || v.Kind() == reflect.Array) {
			for i := 0; i < v.Len(); i++ {
				flattenHelper(v.Index(i).Interface())
			}
		} else {
			res = append(res, item)
		}
	}
	for _, item := range s {
		flattenHelper(item)
	}
	return res, nil
}

func (c *CollFuncs) Reverse(in interface{}) ([]interface{}, error) {
	s, err := toInterfaceSlice(in)
	if err != nil {
		return nil, err
	}
	res := make([]interface{}, len(s))
	for i := 0; i < len(s); i++ {
		res[i] = s[len(s)-1-i]
	}
	return res, nil
}

func (c *CollFuncs) Sort(args ...interface{}) ([]interface{}, error) {
	if len(args) == 0 {
		return []interface{}{}, nil
	}
	in := args[len(args)-1]
	s, err := toInterfaceSlice(in)
	if err != nil {
		return nil, err
	}
	res := make([]interface{}, len(s))
	copy(res, s)
	sort.Slice(res, func(i, j int) bool {
		return fmt.Sprint(res[i]) < fmt.Sprint(res[j])
	})
	return res, nil
}

func (c *CollFuncs) Merge(maps ...interface{}) (map[string]interface{}, error) {
	res := make(map[string]interface{})
	for _, m := range maps {
		if m == nil {
			continue
		}
		v := reflect.ValueOf(m)
		if v.Kind() != reflect.Map {
			return nil, fmt.Errorf("merge expects map")
		}
		for _, mapKey := range v.MapKeys() {
			k := fmt.Sprint(mapKey.Interface())
			val := v.MapIndex(mapKey).Interface()
			res[k] = val
		}
	}
	return res, nil
}

func (c *CollFuncs) Pick(args ...interface{}) (map[string]interface{}, error) {
	if len(args) == 0 {
		return map[string]interface{}{}, nil
	}
	in := args[len(args)-1]
	v := reflect.ValueOf(in)
	if in == nil || v.Kind() != reflect.Map {
		return nil, fmt.Errorf("must be map[string]any, got %T", in)
	}
	keysToKeep := make(map[string]bool)
	for i := 0; i < len(args)-1; i++ {
		keysToKeep[fmt.Sprint(args[i])] = true
	}
	res := make(map[string]interface{})
	for _, mapKey := range v.MapKeys() {
		k := fmt.Sprint(mapKey.Interface())
		if keysToKeep[k] {
			res[k] = v.MapIndex(mapKey).Interface()
		}
	}
	return res, nil
}

func (c *CollFuncs) Omit(args ...interface{}) (map[string]interface{}, error) {
	if len(args) == 0 {
		return map[string]interface{}{}, nil
	}
	in := args[len(args)-1]
	v := reflect.ValueOf(in)
	if in == nil || v.Kind() != reflect.Map {
		return nil, fmt.Errorf("must be map[string]any, got %T", in)
	}
	keysToOmit := make(map[string]bool)
	for i := 0; i < len(args)-1; i++ {
		keysToOmit[fmt.Sprint(args[i])] = true
	}
	res := make(map[string]interface{})
	for _, mapKey := range v.MapKeys() {
		k := fmt.Sprint(mapKey.Interface())
		if !keysToOmit[k] {
			res[k] = v.MapIndex(mapKey).Interface()
		}
	}
	return res, nil
}

func (c *CollFuncs) Set(m interface{}, key string, val interface{}) (map[string]interface{}, error) {
	res := make(map[string]interface{})
	if m != nil {
		v := reflect.ValueOf(m)
		if v.Kind() == reflect.Map {
			for _, mapKey := range v.MapKeys() {
				res[fmt.Sprint(mapKey.Interface())] = v.MapIndex(mapKey).Interface()
			}
		}
	}
	res[key] = val
	return res, nil
}

func (c *CollFuncs) Unset(m interface{}, key string) (map[string]interface{}, error) {
