package funcs

import (
	"fmt"
	"net/url"
	"reflect"
	"strconv"
	"strings"
)

type ConvFuncs struct{}

func (c *ConvFuncs) Bool(v interface{}) bool {
	return c.ToBool(v)
}

func (c *ConvFuncs) Default(def, v interface{}) interface{} {
	if v == nil {
		return def
	}
	val := reflect.ValueOf(v)
	switch val.Kind() {
	case reflect.String:
		if val.String() == "" {
			return def
		}
	case reflect.Slice, reflect.Array, reflect.Map:
		if val.Len() == 0 {
			return def
		}
	case reflect.Bool:
		if !val.Bool() {
			return def
		}
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		if val.Int() == 0 {
			return def
		}
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		if val.Uint() == 0 {
			return def
		}
	case reflect.Float32, reflect.Float64:
		if val.Float() == 0 {
			return def
		}
	}
	return v
}

func (c *ConvFuncs) Join(sep string, list interface{}) (string, error) {
	if list == nil {
		return "", nil
	}
	v := reflect.ValueOf(list)
	if v.Kind() != reflect.Slice && v.Kind() != reflect.Array {
		return "", fmt.Errorf("join expects slice")
	}
	elems := make([]string, v.Len())
	for i := 0; i < v.Len(); i++ {
		elems[i] = fmt.Sprint(v.Index(i).Interface())
	}
	return strings.Join(elems, sep), nil
}

func (c *ConvFuncs) URL(s string) (*url.URL, error) {
	return url.Parse(s)
}

func (c *ConvFuncs) ParseInt(s string, base, bitSize int) (int64, error) {
	return strconv.ParseInt(s, base, bitSize)
}

func (c *ConvFuncs) ParseFloat(s string, bitSize int) (float64, error) {
	return strconv.ParseFloat(s, bitSize)
}

func (c *ConvFuncs) ParseUint(s string, base, bitSize int) (uint64, error) {
	return strconv.ParseUint(s, base, bitSize)
}

func (c *ConvFuncs) Atoi(s string) (int, error) {
	return strconv.Atoi(s)
}

func (c *ConvFuncs) ToBool(v interface{}) bool {
	if v == nil {
		return false
	}
	switch b := v.(type) {
	case bool:
		return b
	case string:
		parsed, _ := strconv.ParseBool(b)
		return parsed
	case int, int64, float64:
		f, _ := toFloat64(v)
		return f != 0
	default:
		return false
	}
}

func (c *ConvFuncs) ToBools(v interface{}) []bool {
