func (c *CryptoFuncs) MD5(v interface{}) string {
	return hex.EncodeToString(c.MD5Bytes(v))
}

func (c *CryptoFuncs) Bcrypt(args ...interface{}) (string, error) {
	if len(args) == 0 {
		return "", fmt.Errorf("bcrypt requires input")
	}
	cost := bcrypt.DefaultCost
	input := ""
	if len(args) == 1 {
		input = fmt.Sprint(args[0])
	} else {
		cVal, _ := toInt64(args[0])
		if cVal > 0 {
			cost = int(cVal)
		}
		input = fmt.Sprint(args[1])
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(input), cost)
	if err != nil {
		return "", err
	}
	return string(hash), nil
}

func (c *CryptoFuncs) EncryptAES(key, plaintext interface{}) (string, error) {
	k := []byte(fmt.Sprint(key))
	pt := []byte(fmt.Sprint(plaintext))
	block, err := aes.NewCipher(k)
	if err != nil {
		return "", err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return "", err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		return "", err
	}
	ciphertext := gcm.Seal(nonce, nonce, pt, nil)
	return hex.EncodeToString(ciphertext), nil
}

func (c *CryptoFuncs) DecryptAESBytes(key, ciphertext interface{}) ([]byte, error) {
	k := []byte(fmt.Sprint(key))
	ct, err := hex.DecodeString(fmt.Sprint(ciphertext))
	if err != nil {
		return nil, err
	}
	block, err := aes.NewCipher(k)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonceSize := gcm.NonceSize()
	if len(ct) < nonceSize {
		return nil, fmt.Errorf("ciphertext too short")
	}
	nonce, ct := ct[:nonceSize], ct[nonceSize:]
	return gcm.Open(nil, nonce, ct, nil)
}

func (c *CryptoFuncs) DecryptAES(key, ciphertext interface{}) (string, error) {
	b, err := c.DecryptAESBytes(key, ciphertext)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

func (c *CryptoFuncs) PBKDF2(pass, salt interface{}, iter, keyLen int, hashAlg string) ([]byte, error) {
	p := []byte(fmt.Sprint(pass))
	s := []byte(fmt.Sprint(salt))
	hFunc := sha256.New
	if hashAlg == "sha1" {
		hFunc = sha1.New
	} else if hashAlg == "sha512" {
		hFunc = sha512.New
	}
	return pbkdf2.Key(p, s, iter, keyLen, hFunc), nil
