	info, err := os.Stat(path)
	if err != nil {
		return false
	}
	return info.IsDir()
}

func (f *FileFuncs) Read(path string) (string, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

func (f *FileFuncs) ReadDir(path string) ([]string, error) {
	entries, err := os.ReadDir(path)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, entry := range entries {
		names = append(names, entry.Name())
	}
	return names, nil
}

func (f *FileFuncs) Stat(path string) (os.FileInfo, error) {
	return os.Stat(path)
}

func (f *FileFuncs) Walk(path string) ([]string, error) {
	var files []string
	err := filepath.Walk(path, func(p string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		files = append(files, p)
		return nil
	})
	return files, err
}

func (f *FileFuncs) Write(path string, content interface{}) error {
	var b []byte
	switch c := content.(type) {
	case []byte:
		b = c
	default:
		b = []byte(f.ReadString(content))
	}
	return os.WriteFile(path, b, 0644)
}

func (f *FileFuncs) ReadString(content interface{}) string {
	if content == nil {
		return ""
	}
	if s, ok := content.(string); ok {
		return s
	}
	return ""
}
