package funcs

import (
	"crypto/rand"
	"fmt"
	"math/big"
	"math/rand/v2"
	"reflect"
	"regexp"
)

type RandomFuncs struct{}

func (r *RandomFuncs) ASCII(count int) (string, error) {
	const chars = " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~"
	return randomStringFromChars(count, chars)
}

func (r *RandomFuncs) Alpha(count int) (string, error) {
	const chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
	return randomStringFromChars(count, chars)
}

func (r *RandomFuncs) AlphaNum(count int) (string, error) {
	const chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
	return randomStringFromChars(count, chars)
}

func (r *RandomFuncs) String(args ...interface{}) (string, error) {
	if len(args) == 0 {
		return "", fmt.Errorf("random.String requires count")
	}
	countVal, err := toInt64(args[0])
	if err != nil {
		return "", err
	}
	count := int(countVal)
	if count <= 0 {
		return "", nil
	}

	charSet := "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-"
	if len(args) > 1 {
		pattern := fmt.Sprint(args[1])
		re, err := regexp.Compile(pattern)
		if err == nil {
			var runes []rune
			for i := 0; i < 0x10ffff; i++ {
				r := rune(i)
				if re.MatchString(string(r)) {
					runes = append(runes, r)
					if len(runes) > 1000 {
						break
					}
				}
			}
			if len(runes) > 0 {
				res := make([]rune, count)
				for i := 0; i < count; i++ {
					idx, _ := rand.Int(rand.Reader, big.NewInt(int64(len(runes))))
					res[i] = runes[idx.Int64()]
				}
				return string(res), nil
			}
		}
	}

	return randomStringFromChars(count, charSet)
}

func randomStringFromChars(count int, chars string) (string, error) {
	if count <= 0 {
		return "", nil
	}
	runes := []rune(chars)
	res := make([]rune, count)
	for i := 0; i < count; i++ {
		idx, err := rand.Int(rand.Reader, big.NewInt(int64(len(runes))))
		if err != nil {
			return "", err
		}
		res[i] = runes[idx.Int64()]
	}
	return string(res), nil
}

func (r *RandomFuncs) Item(in interface{}) (interface{}, error) {
	s, err := toInterfaceSlice(in)
	if err != nil || len(s) == 0 {
		return nil, err
	}
	idx, _ := rand.Int(rand.Reader, big.NewInt(int64(len(s))))
	return s[idx.Int64()], nil
}

func (r *RandomFuncs) Number(args ...interface{}) (int64, error) {
	var minVal, maxVal int64 = 0, 100
	if len(args) == 1 {
		max, err := toInt64(args[0])
		if err != nil {
			return 0, err
		}
		maxVal = max
	} else if len(args) >= 2 {
		min, err1 := toInt64(args[0])
		max, err2 := toInt64(args[1])
		if err1 != nil || err2 != nil {
			return 0, fmt.Errorf("invalid range")
		}
		minVal = min
		maxVal = max
	}
	if minVal >= maxVal {
		return minVal, nil
	}
	diff := maxVal - minVal + 1
	n, _ := rand.Int(rand.Reader, big.NewInt(diff))
	return minVal + n.Int64(), nil
}

func (r *RandomFuncs) Float(args ...interface{}) (float64, error) {
	var minVal, maxVal float64 = 0.0, 1.0
	if len(args) == 1 {
		max, err := toFloat64(args[0])
		if err != nil {
			return 0, err
		}
		maxVal = max
	} else if len(args) >= 2 {
		min, err1 := toFloat64(args[0])
		max, err2 := toFloat64(args[1])
		if err1 != nil || err2 != nil {
			return 0, fmt.Errorf("invalid range")
		}
		minVal = min
		maxVal = max
	}
	if minVal >= maxVal {
		return minVal, nil
	}
	f := rand.Float64()
	return minVal + f*(maxVal-minVal), nil
}

func reflectValue(v interface{}) reflect.Value {
	return reflect.ValueOf(v)
}
EOF
"}

