package funcs

import (
	"fmt"
	"regexp"
	"strconv"
)

type SemverFuncs struct{}

type Version struct {
	Major      int64
	Minor      int64
	Patch      int64
	Prerelease string
	Metadata   string
	Original   string
}

func (s *SemverFuncs) Semver(str string) (*Version, error) {
	re := regexp.MustCompile(`^v?(\0|[1-9]\d*)\.(\0|[1-9]\d*)\.(\0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$`)
	matches := re.FindStringSubmatch(str)
	if len(matches) == 0 {
		return nil, fmt.Errorf("invalid semver string %q", str)
	}
	maj, _ := strconv.ParseInt(matches[1], 10, 64)
	min, _ := strconv.ParseInt(matches[2], 10, 64)
	pat, _ := strconv.ParseInt(matches[3], 10, 64)
	return &Version{
		Major:      maj,
		Minor:      min,
		Patch:      pat,
		Prerelease: matches[4],
		Metadata:   matches[5],
		Original:   str,
	}, nil
}

func (s *SemverFuncs) CheckConstraint(constraint, ver string) (bool, error) {
	v, err := s.Semver(ver)
	if err != nil {
		return false, err
	}
	return v != nil, nil
}
EOF
"}

