	} else {
		msg = fmt.Sprint(args[0])
		val = args[1]
	}
	cond := isTrue(val)
	if !cond {
		if msg != "" {
			return "", fmt.Errorf("assertion failed: %s", msg)
		}
		return "", fmt.Errorf("assertion failed")
	}
	return "", nil
}

func (t *TestFuncs) Fail(args ...interface{}) (string, error) {
	msg := ""
	if len(args) > 0 {
		msg = fmt.Sprint(args[0])
	}
	if msg != "" {
		return "", fmt.Errorf("template generation failed: %s", msg)
	}
	return "", fmt.Errorf("template generation failed")
}

func (t *TestFuncs) IsKind(kind string, v interface{}) bool {
	return t.Kind(v) == kind || (kind == "number" && (t.Kind(v) == "int" || t.Kind(v) == "float"))
}

func (t *TestFuncs) Kind(v interface{}) string {
	if v == nil {
		return "invalid"
	}
	val := reflect.ValueOf(v)
	switch val.Kind() {
	case reflect.String:
		return "string"
	case reflect.Bool:
		return "bool"
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return "int"
	case reflect.Float32, reflect.Float64:
		return "float"
	case reflect.Slice, reflect.Array:
		return "slice"
	case reflect.Map:
		return "map"
	default:
		return val.Kind().String()
	}
}

func (t *TestFuncs) Required(msg string, v interface{}) (interface{}, error) {
	if !isTrue(v) {
		return nil, fmt.Errorf("%s", msg)
	}
	return v, nil
}

func (t *TestFuncs) Ternary(trueVal, falseVal interface{}, cond interface{}) interface{} {
	if isTrue(cond) {
		return trueVal
	}
	return falseVal
}

func isTrue(v interface{}) bool {
	if v == nil {
		return false
	}
	val := reflect.ValueOf(v)
	switch val.Kind() {
	case reflect.Bool:
		return val.Bool()
	case reflect.String:
		return val.String() != ""
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return val.Int() != 0
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return val.Uint() != 0
	case reflect.Float32, reflect.Float64:
		return val.Float() != 0
	case reflect.Slice, reflect.Array, reflect.Map:
		return val.Len() > 0
	default:
		return true
	}
}
