package funcs

import (
	"bytes"
	"fmt"
	"text/template"
)

type TmplFuncs struct {
	RootTemplate *template.Template
	FuncsMap     template.FuncMap
	CurrentPath  string
}

func (t *TmplFuncs) Exec(name string, ctx ...interface{}) (string, error) {
	if t.RootTemplate == nil {
		return "", fmt.Errorf("no root template")
	}
	tmpl := t.RootTemplate.Lookup(name)
	if tmpl == nil {
		return "", fmt.Errorf("template %q not found", name)
	}
	var data interface{}
	if len(ctx) > 0 {
		data = ctx[0]
	}
	var buf bytes.Buffer
	err := tmpl.Execute(&buf, data)
	if err != nil {
		return "", err
	}
	return buf.String(), nil
}

func (t *TmplFuncs) Inline(inlineTpl string, ctx ...interface{}) (string, error) {
	var data interface{}
	if len(ctx) > 0 {
		data = ctx[0]
	}
	tpl := template.New("inline")
	if t.FuncsMap != nil {
		tpl = tpl.Funcs(t.FuncsMap)
	}
	parsed, err := tpl.Parse(inlineTpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	err = parsed.Execute(&buf, data)
	if err != nil {
		return "", err
	}
	return buf.String(), nil
}

func (t *TmplFuncs) Path() string {
	return t.CurrentPath
}

func (t *TmplFuncs) PathDir() string {
	return t.CurrentPath
}
EOF
"}

