}

func (n *NetFuncs) CIDRHost(hostNum int, prefix string) (string, error) {
	_, ipNet, err := net.ParseCIDR(prefix)
	if err != nil {
		return "", err
	}
	ip := ipNet.IP.To4()
	if ip == nil {
		ip = ipNet.IP.To16()
	}
	resIP := make(net.IP, len(ip))
	copy(resIP, ip)
	if hostNum < 0 {
		maskLen, bitLen := ipNet.Mask.Size()
		hosts := (1 << (bitLen - maskLen)) + hostNum
		hostNum = hosts
	}
	for i := len(resIP) - 1; i >= 0; i-- {
		resIP[i] += byte(hostNum)
		hostNum >>= 8
	}
	return resIP.String(), nil
}

func (n *NetFuncs) CIDRNetmask(prefix string) (string, error) {
	_, ipNet, err := net.ParseCIDR(prefix)
	if err != nil {
		return "", err
	}
	return net.IP(ipNet.Mask).String(), nil
