package datasources

import (
	"encoding/csv"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"

	"github.com/BurntSushi/toml"
	"gopkg.in/yaml.v3"
)

type Source struct {
	Alias  string
	URL    string
	Header http.Header
}

type Store struct {
	sources map[string]*Source
	cache   map[string]interface{}
	stdin   []byte
}

func NewStore() *Store {
	return &Store{
		sources: make(map[string]*Source),
		cache:   make(map[string]interface{}),
	}
}

func (s *Store) SetStdin(data []byte) {
	s.stdin = data
}

func (s *Store) Define(alias, rawURL string, header ...http.Header) {
	var h http.Header
	if len(header) > 0 {
		h = header[0]
	}
	s.sources[alias] = &Source{
		Alias:  alias,
		URL:    rawURL,
		Header: h,
	}
}

func (s *Store) Exists(alias string) bool {
	_, ok := s.sources[alias]
	return ok
}

func (s *Store) Reachable(alias string) bool {
	return s.Exists(alias)
}

func (s *Store) List() []string {
	var res []string
	for k := range s.sources {
		res = append(res, k)
	}
	return res
}

func (s *Store) ReadRaw(alias string, subpath ...string) (string, []byte, error) {
	src, ok := s.sources[alias]
	if !ok {
		// If alias looks like a file path or URL directly:
		src = &Source{Alias: alias, URL: alias}
	}

	u, err := url.Parse(src.URL)
	if err != nil {
		return "", nil, err
	}

	targetURL := src.URL
	if len(subpath) > 0 && subpath[0] != "" {
		targetURL = strings.TrimRight(targetURL, "/") + "/" + strings.TrimLeft(subpath[0], "/")
		u, _ = url.Parse(targetURL)
	}

	var data []byte
	var ext string

	switch u.Scheme {
	case "stdin":
		data = s.stdin
		ext = filepath.Ext(u.Path)
	case "env":
		key := strings.TrimPrefix(u.Path, "/")
		if key == "" {
			key = u.Opaque
		}
		data = []byte(os.Getenv(key))
		ext = filepath.Ext(key)
	case "http", "https":
		req, err := http.NewRequest("GET", targetURL, nil)
		if err != nil {
			return "", nil, err
		}
		if src.Header != nil {
			req.Header = src.Header
		}
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			return "", nil, err
		}
		defer resp.Body.Close()
		data, err = io.ReadAll(resp.Body)
		if err != nil {
			return "", nil, err
		}
		ext = filepath.Ext(u.Path)
	default:
		// file:// or relative/absolute path
		filePath := targetURL
		if strings.HasPrefix(filePath, "file://") {
			filePath = strings.TrimPrefix(filePath, "file://")
		}
		b, err := os.ReadFile(filePath)
		if err != nil {
			return "", nil, err
		}
		data = b
		ext = filepath.Ext(filePath)
	}

	if qType := u.Query().Get("type"); qType != "" {
		ext = "." + qType
	}

	return ext, data, nil
}

func (s *Store) Read(alias string, subpath ...string) (interface{}, error) {
	cacheKey := alias
	if len(subpath) > 0 && subpath[0] != "" {
		cacheKey = alias + ":" + subpath[0]
	}
	if v, ok := s.cache[cacheKey]; ok {
		return v, nil
	}

	ext, data, err := s.ReadRaw(alias, subpath...)
	if err != nil {
		return nil, err
	}

	var parsed interface{}

	switch strings.ToLower(ext) {
	case ".json":
		err = json.Unmarshal(data, &parsed)
	case ".yaml", ".yml":
		err = yaml.Unmarshal(data, &parsed)
	case ".toml":
		_, err = toml.Decode(string(data), &parsed)
	case ".csv":
		r := csv.NewReader(strings.NewReader(string(data)))
		rows, csvErr := r.ReadAll()
		if csvErr == nil {
			parsed = rows
		} else {
			err = csvErr
		}
	default:
		// Try JSON then YAML, fallback to string
		if json.Unmarshal(data, &parsed) != nil {
			if yaml.Unmarshal(data, &parsed) != nil {
				parsed = string(data)
			}
		}
	}

	if err != nil {
		return string(data), nil
	}

	s.cache[cacheKey] = parsed
	return parsed, nil
}

func (s *Store) ReadInclude(alias string, subpath ...string) (string, error) {
	_, data, err := s.ReadRaw(alias, subpath...)
	if err != nil {
		return "", err
	}
	return string(data), nil
}
EOF
"}

