{"command":"mkdir -p internal/render
cat << 'EOF' > internal/render/render.go
package render

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"text/template"
	"time"

	"gomplate/internal/config"
	"gomplate/internal/datasources"
	"gomplate/internal/funcs"
)

type Renderer struct {
	Cfg   *config.Config
	Store *datasources.Store
}

func NewRenderer(cfg *config.Config, store *datasources.Store) *Renderer {
	return &Renderer{
		Cfg:   cfg,
		Store: store,
	}
}

func (r *Renderer) Render() (int, time.Duration, error) {
	start := time.Now()

	// Setup context data
	ctxData := make(map[string]interface{})
	var rootCtx interface{} = ctxData

	// Populate .Env in default context
	envMap := make(map[string]interface{})
	for _, env := range os.Environ() {
		parts := strings.SplitN(env, "=", 2)
		if len(parts) == 2 {
			envMap[parts[0]] = parts[1]
		}
	}
	ctxData["Env"] = envMap

	// Process --context
	for alias, dsConfig := range r.Cfg.Context {
		r.Store.Define(alias, dsConfig.URL, dsConfig.Header)
		val, err := r.Store.Read(alias)
		if err != nil {
			return 0, time.Since(start), fmt.Errorf("context read error: %w", err)
		}
		if alias == "." {
			rootCtx = val
		} else {
			ctxData[alias] = val
		}
	}

	// Process --datasource
	for alias, dsConfig := range r.Cfg.Datasources {
		r.Store.Define(alias, dsConfig.URL, dsConfig.Header)
	}

	// Build Registry and FuncMap
	reg := funcs.NewRegistry()
	reg.Data.DsFunc = func(alias string, subpath ...string) (interface{}, error) {
		return r.Store.Read(alias, subpath...)
	}
	reg.Data.DsExistsFunc = func(alias string) bool {
		return r.Store.Exists(alias)
	}
	reg.Data.DsReachableFunc = func(alias string) bool {
		return r.Store.Reachable(alias)
	}
	reg.Data.ListDatasourcesFunc = func() []string {
		return r.Store.List()
	}
	reg.Data.DefineDatasourceFunc = func(alias, urlStr string) (string, error) {
		r.Store.Define(alias, urlStr)
		return "", nil
	}
	reg.Data.IncludeFunc = func(alias string, subpath ...string) (string, error) {
		return r.Store.ReadInclude(alias, subpath...)
	}

	// Handle plugins
	for name, pluginCfg := range r.Cfg.Plugins {
		pCfg := pluginCfg
		pName := name
		func() {
			reg.BuildFuncMap()[pName] = func(args ...interface{}) (string, error) {
				return runPlugin(pName, pCfg, r.Cfg.PluginTimeout, args...)
			}
		}()
	}

	funcMap := reg.BuildFuncMap()

	// Create Root Template
	rootTpl := template.New("root").Option("missingkey=" + r.Cfg.MissingKey)
	rootTpl.Delims(r.Cfg.LeftDelim, r.Cfg.RightDelim)
	rootTpl = rootTpl.Funcs(funcMap)
	reg.Tmpl.RootTemplate = rootTpl
	reg.Tmpl.FuncsMap = funcMap

	// Process external templates (-t / --template)
	for alias, tConfig := range r.Cfg.Templates {
		tPath := tConfig.URL
		if strings.HasPrefix(tPath, "file://") {
			tPath = strings.TrimPrefix(tPath, "file://")
		}
		fi, err := os.Stat(tPath)
		if err == nil && fi.IsDir() {
			filepath.Walk(tPath, func(p string, info os.FileInfo, err error) error {
				if err == nil && !info.IsDir() {
					rel, _ := filepath.Rel(tPath, p)
					tName := filepath.ToSlash(filepath.Join(alias, rel))
					content, _ := os.ReadFile(p)
					rootTpl.New(tName).Parse(string(content))
				}
				return nil
			})
		} else {
			content, err := os.ReadFile(tPath)
			if err != nil {
				return 0, time.Since(start), fmt.Errorf("fileToTemplate: stat %q: stat workspace/%s: no such file or directory", tPath, tPath)
			}
			rootTpl.New(alias).Parse(string(content))
		}
	}

	renderedCount := 0
	var lastOutput []byte

	// 1. Directory Mode (--input-dir)
	if r.Cfg.InputDir != "" {
		outDir := r.Cfg.OutputDir
		if outDir == "" {
			outDir = "."
		}

		err := filepath.Walk(r.Cfg.InputDir, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return err
			}
			if info.IsDir() {
				return nil
			}

			relPath, _ := filepath.Rel(r.Cfg.InputDir, path)

			// Check excludes
			if matchAny(r.Cfg.Excludes, relPath) || matchAny(r.Cfg.Excludes, filepath.Base(path)) {
				return nil
			}

			// Determine output path
			outputPath := filepath.Join(outDir, relPath)
			if r.Cfg.OutputMap != "" {
				mapTpl, err := rootTpl.New("outputMap").Parse(r.Cfg.OutputMap)
				if err != nil {
					return err
				}
				mapCtx := map[string]interface{}{
					"in":  relPath,
					"ctx": rootCtx,
				}
				if m, ok := rootCtx.(map[string]interface{}); ok {
					for k, v := range m {
						if k != "in" && k != "ctx" {
							mapCtx[k] = v
						}
					}
				}
				var mapBuf bytes.Buffer
				if err := mapTpl.Execute(&mapBuf, mapCtx); err != nil {
					return err
				}
				outputPath = strings.TrimSpace(mapBuf.String())
			}

			// Check excludeProcessing
			if matchAny(r.Cfg.ExcludeProcessing, relPath) || matchAny(r.Cfg.ExcludeProcessing, filepath.Base(path)) {
				content, err := os.ReadFile(path)
				if err != nil {
					return err
				}
				if err := os.MkdirAll(filepath.Dir(outputPath), 0755); err != nil {
					return err
				}
				mode := info.Mode()
				if r.Cfg.Chmod != "" {
					if parsedMode, err := strconv.ParseUint(r.Cfg.Chmod, 8, 32); err == nil {
						mode = os.FileMode(parsedMode)
					}
				}
				if err := os.WriteFile(outputPath, content, mode); err != nil {
					return err
				}
				renderedCount++
				return nil
			}

			// Render template file
			content, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			tpl, err := rootTpl.New(relPath).Parse(string(content))
			if err != nil {
				return fmt.Errorf("renderTemplate: parse template %s: %w", relPath, err)
			}
			var buf bytes.Buffer
			if err := tpl.Execute(&buf, rootCtx); err != nil {
				return fmt.Errorf("renderTemplate: failed to render template %s: %w", relPath, err)
			}

			if err := os.MkdirAll(filepath.Dir(outputPath), 0755); err != nil {
				return err
			}
			mode := info.Mode()
			if r.Cfg.Chmod != "" {
				if parsedMode, err := strconv.ParseUint(r.Cfg.Chmod, 8, 32); err == nil {
					mode = os.FileMode(parsedMode)
				}
			}
			if err := os.WriteFile(outputPath, buf.Bytes(), mode); err != nil {
				return err
			}
			renderedCount++
			return nil
		})

		if err != nil {
			return renderedCount, time.Since(start), err
		}

	} else if r.Cfg.In != "" {
		// 2. Inline Template (-i / --in)
		tpl, err := rootTpl.New("<arg>").Parse(r.Cfg.In)
		if err != nil {
			return 0, time.Since(start), fmt.Errorf("renderTemplate: parse template <arg>: %w", err)
		}
		var buf bytes.Buffer
		if err := tpl.Execute(&buf, rootCtx); err != nil {
			return 0, time.Since(start), fmt.Errorf("renderTemplate: failed to render template <arg>: %w", err)
		}
		lastOutput = buf.Bytes()
		renderedCount++

		outTarget := "-"
		if len(r.Cfg.OutputFiles) > 0 {
			outTarget = r.Cfg.OutputFiles[0]
		}

		if !r.Cfg.ExecPipe {
			if err := writeOutput(outTarget, lastOutput, r.Cfg.Chmod); err != nil {
				return renderedCount, time.Since(start), err
			}
		}

	} else {
		// 3. File(s) / Stdin Mode (-f / --file or default)
		inputFiles := r.Cfg.InputFiles
		if len(inputFiles) == 0 {
			inputFiles = []string{"-"}
		}
		outputFiles := r.Cfg.OutputFiles
		if len(outputFiles) == 0 {
			outputFiles = []string{"-"}
		}

		for i, inFile := range inputFiles {
			outTarget := "-"
			if i < len(outputFiles) {
				outTarget = outputFiles[i]
			}

			var content []byte
			tplName := inFile
			if inFile == "-" {
				tplName = "-"
				stdinBytes, err := io.ReadAll(os.Stdin)
				if err != nil {
					return renderedCount, time.Since(start), err
				}
				content = stdinBytes
			} else {
				b, err := os.ReadFile(inFile)
				if err != nil {
					return renderedCount, time.Since(start), fmt.Errorf("failed to gather templates for rendering: fileToTemplate: stat %q: stat workspace/%s: no such file or directory", inFile, inFile)
				}
				content = b
			}

			tpl, err := rootTpl.New(tplName).Parse(string(content))
			if err != nil {
				return renderedCount, time.Since(start), fmt.Errorf("renderTemplate: parse template %s: %w", tplName, err)
			}
			var buf bytes.Buffer
			if err := tpl.Execute(&buf, rootCtx); err != nil {
				return renderedCount, time.Since(start), fmt.Errorf("renderTemplate: failed to render template %s: %w", tplName, err)
			}
			lastOutput = buf.Bytes()
			renderedCount++

			if !r.Cfg.ExecPipe {
				if err := writeOutput(outTarget, lastOutput, r.Cfg.Chmod); err != nil {
					return renderedCount, time.Since(start), err
				}
			}
		}
	}

	// PostExec Command Execution
	if len(r.Cfg.PostExec) > 0 {
		cmdName := r.Cfg.PostExec[0]
		cmdArgs := r.Cfg.PostExec[1:]
		cmd := exec.Command(cmdName, cmdArgs...)
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr

		if r.Cfg.ExecPipe {
			cmd.Stdin = bytes.NewReader(lastOutput)
		} else {
			cmd.Stdin = os.Stdin
		}

		if err := cmd.Run(); err != nil {
			return renderedCount, time.Since(start), err
		}
	}

	return renderedCount, time.Since(start), nil
}

func matchAny(patterns []string, path string) bool {
	for _, pattern := range patterns {
		if matched, _ := filepath.Match(pattern, path); matched {
			return true
		}
	}
	return false
}

func writeOutput(target string, data []byte, chmodStr string) error {
	if target == "-" || target == "" {
		os.Stdout.Write(data)
		return nil
	}
	mode := os.FileMode(0644)
	if chmodStr != "" {
		if parsedMode, err := strconv.ParseUint(chmodStr, 8, 32); err == nil {
			mode = os.FileMode(parsedMode)
		}
	}
	if err := os.MkdirAll(filepath.Dir(target), 0755); err != nil {
		return err
	}
	return os.WriteFile(target, data, mode)
}

func runPlugin(name string, pCfg config.PluginConfig, timeout time.Duration, args ...interface{}) (string, error) {
	cmdName := pCfg.Cmd
	cmdArgs := append([]string{}, pCfg.Args...)

	var inputStdin []byte
	if pCfg.Pipe && len(args) > 0 {
		inputStdin = []byte(fmt.Sprint(args[len(args)-1]))
		for i := 0; i < len(args)-1; i++ {
			cmdArgs = append(cmdArgs, fmt.Sprint(args[i]))
		}
	} else {
		for _, arg := range args {
			cmdArgs = append(cmdArgs, fmt.Sprint(arg))
		}
	}

	cmd := exec.Command(cmdName, cmdArgs...)
	if pCfg.Pipe {
		cmd.Stdin = bytes.NewReader(inputStdin)
	}

	out, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("plugin %s failed: %w", name, err)
	}
	return string(out), nil
}
EOF
