			slog.SetDefault(logger)

			if cfg.Verbose {
				logger.Debug("starting gomplate")
				inDesc := cfg.In
				if inDesc == "" && len(cfg.InputFiles) > 0 {
					inDesc = strings.Join(cfg.InputFiles, ", ")
				}
				logger.Debug(fmt.Sprintf("config is:\n---\nin: %s\n", inDesc), "version", "0.0.0", "build", "HEAD")
			}

