package pbkdf2

import (
	"hash"
)

func Key(password, salt []byte, iter, keyLen int, h func() hash.Hash) []byte {
	prf := h()
	hashLen := prf.Size()
	numBlocks := (keyLen + hashLen - 1) / hashLen
	var dk []byte
	U := make([]byte, hashLen)
	for block := 1; block <= numBlocks; block++ {
		prf.Reset()
		prf.Write(password)
		prf.Write(salt)
		prf.Write([]byte{byte(block >> 24), byte(block >> 16), byte(block >> 8), byte(block)})
		U = prf.Sum(U[:0])
		T := make([]byte, hashLen)
		copy(T, U)
		for i := 2; i <= iter; i++ {
			prf.Reset()
			prf.Write(password)
			prf.Write(U)
			U = prf.Sum(U[:0])
			for k := 0; k < hashLen; k++ {
				T[k] ^= U[k]
			}
		}
		dk = append(dk, T...)
	}
	return dk[:keyLen]
}
EOF

