{"command":"cat << 'EOF' > main.go
package main

import (
	"context"
	"fmt"
	"log/slog"
	"os"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"gomplate/internal/config"
	"gomplate/internal/datasources"
	"gomplate/internal/render"
