	inputDirFlag           string
	excludeFlag            []string
	excludeProcFlag        []string
	includeFlag            []string
	outFlag                []string
	templatesFlag          []string
	outputDirFlag          string
	outputMapFlag          string
	chmodFlag              string
	execPipeFlag           bool
	leftDelimFlag          string
	rightDelimFlag         string
	missingKeyFlag         string
	experimentalFlag       bool
	verboseFlag            bool
	configFlag             string
	versionFlag            bool
)

func main() {
	var rootCmd = &cobra.Command{
		Use:   "gomplate",
		Short: "Process text files with Go templates",
		Long:  "Process text files with Go templates",
		Args:  cobra.ArbitraryArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if versionFlag {
				fmt.Println("gomplate version 0.0.0")
				return nil
			}

			// Determine config file path
			cfgPath := configFlag
			if !cmd.Flags().Changed("config") {
				if envCfg := os.Getenv("GOMPLATE_CONFIG"); envCfg != "" {
					cfgPath = envCfg
				}
			}

			// Load config file if it exists and wasn't explicitly disabled
			var cfg *config.Config
			var err error
			if cfgPath != "" {
				if _, statErr := os.Stat(cfgPath); statErr == nil {
					cfg, err = config.LoadConfigFile(cfgPath)
					if err != nil {
						return fmt.Errorf("config file requested, but couldn't be opened: %w", err)
					}
				} else if cmd.Flags().Changed("config") {
					return fmt.Errorf("config file requested, but couldn't be opened: %w", statErr)
				}
			}

			if cfg == nil {
				cfg = config.NewDefaultConfig()
			}

			// Override config with CLI flags if set
			if cmd.Flags().Changed("in") {
				cfg.In = inFlag
			}
			if cmd.Flags().Changed("file") {
				cfg.InputFiles = filesFlag
			}
			if cmd.Flags().Changed("input-dir") {
				cfg.InputDir = inputDirFlag
			}
			if cmd.Flags().Changed("out") {
				cfg.OutputFiles = outFlag
			}
			if cmd.Flags().Changed("output-dir") {
				cfg.OutputDir = outputDirFlag
			}
			if cmd.Flags().Changed("output-map") {
				cfg.OutputMap = outputMapFlag
			}
			if cmd.Flags().Changed("exclude") {
				cfg.Excludes = excludeFlag
			}
			if cmd.Flags().Changed("include") {
				cfg.Includes = includeFlag
			}
			if cmd.Flags().Changed("exclude-processing") {
				cfg.ExcludeProcessing = excludeProcFlag
			}
			if cmd.Flags().Changed("chmod") {
				cfg.Chmod = chmodFlag
			}
			if cmd.Flags().Changed("exec-pipe") {
				cfg.ExecPipe = execPipeFlag
			}
			if cmd.Flags().Changed("left-delim") {
				cfg.LeftDelim = leftDelimFlag
			}
			if cmd.Flags().Changed("right-delim") {
				cfg.RightDelim = rightDelimFlag
			}
			if cmd.Flags().Changed("missing-key") {
				cfg.MissingKey = missingKeyFlag
			}
			if cmd.Flags().Changed("experimental") {
				cfg.Experimental = experimentalFlag
			}
			if cmd.Flags().Changed("verbose") {
				cfg.Verbose = verboseFlag
			}

			// Process -d / --datasource
			for _, ds := range datasourcesFlag {
				parts := strings.SplitN(ds, "=", 2)
				if len(parts) == 2 {
					cfg.Datasources[parts[0]] = config.DataSourceConfig{URL: parts[1]}
				}
			}

			// Process -c / --context
			for _, ctx := range contextFlag {
				parts := strings.SplitN(ctx, "=", 2)
				if len(parts) == 2 {
					cfg.Context[parts[0]] = config.DataSourceConfig{URL: parts[1]}
				} else {
					cfg.Context["."] = config.DataSourceConfig{URL: ctx}
				}
			}

			// Process -t / --template
			for _, tpl := range templatesFlag {
				parts := strings.SplitN(tpl, "=", 2)
				if len(parts) == 2 {
					cfg.Templates[parts[0]] = config.DataSourceConfig{URL: parts[1]}
				}
			}

			// Process --plugin
			for _, plug := range pluginsFlag {
				parts := strings.SplitN(plug, "=", 2)
				if len(parts) == 2 {
					cfg.Plugins[parts[0]] = config.PluginConfig{Cmd: parts[1]}
				}
			}

			// Trailing args (PostExec)
			if len(args) > 0 {
				cfg.PostExec = args
			}

			// Configure Logger
			logFormat := os.Getenv("GOMPLATE_LOG_FORMAT")
			if logFormat == "" {
				logFormat = "json"
			}

			var handler slog.Handler
			logLevel := slog.LevelError
			if cfg.Verbose {
				logLevel = slog.LevelDebug
			}

			switch logFormat {
			case "simple":
				handler = &SimpleHandler{Level: logLevel}
			case "logfmt":
				handler = &LogfmtHandler{Level: logLevel}
			case "console":
				handler = &ConsoleHandler{Level: logLevel}
			default:
				handler = slog.NewJSONHandler(os.Stderr, &slog.HandlerOptions{Level: logLevel})
			}

			logger := slog.New(handler)
			slog.SetDefault(logger)

			if cfg.Verbose {
				logger.Debug("starting gomplate")
				inDesc := cfg.In
				if inDesc == "" && len(cfg.InputFiles) > 0 {
					inDesc = strings.Join(cfg.InputFiles, ", ")
				}
				logger.Debug(fmt.Sprintf("config is:\n---\nin: %s\n", inDesc), "version", "0.0.0", "build", "HEAD")
			}

			store := datasources.NewStore()
			renderer := render.NewRenderer(cfg, store)

			count, duration, renderErr := renderer.Render()

			if cfg.Verbose {
				errCount := 0
				if renderErr != nil {
					errCount = 1
				}
				logger.Debug("completed rendering", "templatesRendered", count, "errors", errCount, "duration", duration.Nanoseconds())
			}

			if renderErr != nil {
				logger.Error("", "err", renderErr.Error())
				return renderErr
			}

			return nil
		},
	}

	rootCmd.Flags().SortFlags = false
	rootCmd.SetFlagErrorFunc(func(c *cobra.Command, err error) error {
		return err
	})

	rootCmd.Flags().StringArrayVarP(&datasourcesFlag, "datasource", "d", nil, "datasource in alias=URL form. Specify multiple times to add multiple sources.")
	rootCmd.Flags().StringArrayVarP(&datasourceHeadersFlag, "datasource-header", "H", nil, "HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.")
	rootCmd.Flags().StringArrayVarP(&contextFlag, "context", "c", nil, "pre-load a datasource into the context, in alias=URL form. Use the special alias `.` to set the root context.")
	rootCmd.Flags().StringSliceVar(&pluginsFlag, "plugin", nil, "plug in an external command as a function in name=path form. Can be specified multiple times")
	rootCmd.Flags().StringArrayVarP(&filesFlag, "file", "f", nil, "Template file to process. Omit to use standard input, or use --in or --input-dir (default [-])")
	rootCmd.Flags().StringVarP(&inFlag, "in", "i", "", "Template string to process (alternative to --file and --input-dir)")
	rootCmd.Flags().StringVar(&inputDirFlag, "input-dir", "", "directory which is examined recursively for templates (alternative to --file and --in)")
	rootCmd.Flags().StringSliceVar(&excludeFlag, "exclude", nil, "glob of files to not parse")
	rootCmd.Flags().StringSliceVar(&excludeProcFlag, "exclude-processing", nil, "glob of files to be copied without parsing")
	rootCmd.Flags().StringSliceVar(&includeFlag, "include", nil, "glob of files to parse")
	rootCmd.Flags().StringArrayVarP(&outFlag, "out", "o", nil, "output file name. Omit to use standard output. (default [-])")
	rootCmd.Flags().StringSliceVarP(&templatesFlag, "template", "t", nil, "Additional template file(s)")
	rootCmd.Flags().StringVar(&outputDirFlag, "output-dir", ".", "directory to store the processed templates. Only used for --input-dir")
	rootCmd.Flags().StringVar(&outputMapFlag, "output-map", "", "Template string to map the input file to an output path")
	rootCmd.Flags().StringVar(&chmodFlag, "chmod", "", "set the mode for output file(s). Omit to inherit from input file(s)")
	rootCmd.Flags().BoolVar(&execPipeFlag, "exec-pipe", false, "pipe the output to the post-run exec command")
	rootCmd.Flags().StringVar(&leftDelimFlag, "left-delim", "{{", "override the default left-delimiter [$GOMPLATE_LEFT_DELIM]")
	rootCmd.Flags().StringVar(&rightDelimFlag, "right-delim", "}}", "override the default right-delimiter [$GOMPLATE_RIGHT_DELIM]")
	rootCmd.Flags().StringVar(&missingKeyFlag, "missing-key", "error", "Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value>")
	rootCmd.Flags().BoolVar(&experimentalFlag, "experimental", false, "enable experimental features [$GOMPLATE_EXPERIMENTAL]")
	rootCmd.Flags().BoolVarP(&verboseFlag, "verbose", "V", false, "output extra information about what gomplate is doing")
	rootCmd.Flags().StringVar(&configFlag, "config", ".gomplate.yaml", "config file (overridden by commandline flags)")
	rootCmd.Flags().BoolVarP(&versionFlag, "version", "v", false, "version for gomplate")

	rootCmd.SilenceUsage = false
	rootCmd.SilenceErrors = true

	if err := rootCmd.Execute(); err != nil {
		if strings.HasPrefix(err.Error(), "unknown flag") || strings.HasPrefix(err.Error(), "flag needs an argument") {
